INSERT INTO notices (notice_id, title, description, created_by, target_role, created_at, status) VALUES
  (1, 'Mid-semester examination timetable released', 'The Level 2 Semester 1 mid-semester examination timetable is now available. Please check the faculty notice board and the LMS for venue details.', 1, 'ALL', '2026-08-20 09:15:00', 'ACTIVE'),
  (2, 'Medical certificate submission deadline', 'Medical certificates for absences must be submitted to the Technical Officer within 14 days of the absence. Late submissions will not be considered for attendance.', 1, 'UNDERGRADUATE', '2026-08-01 08:30:00', 'ACTIVE'),
  (3, 'Final examination eligibility', 'Students must have at least 80% attendance (approved medicals considered) and at least 40% of the continuous assessment marks to sit the final examination.', 1, 'UNDERGRADUATE', '2026-10-10 10:00:00', 'ACTIVE'),
  (4, 'Marks upload deadline', 'All lecturers are requested to upload CA marks for Level 2 Semester 1 course units before 30th October 2026.', 1, 'LECTURER', '2026-10-05 11:00:00', 'ACTIVE'),
  (5, 'Laboratory maintenance', 'Computer Lab 02 will be closed for maintenance on Saturday. Technical officers please update the practical attendance registers before Friday.', 1, 'TO', '2026-09-28 15:45:00', 'ACTIVE'),
  (6, 'ICT2132 mini project presentations', 'Mini project evaluations will be held on 5th November 2026. Each group gets 15 minutes for the presentation and 10 minutes for the discussion.', 1, 'ALL', '2026-10-28 09:00:00', 'ACTIVE'),
  (7, 'Faculty sports day (postponed)', 'The faculty sports day has been postponed. A new date will be announced.', 1, 'ALL', '2026-07-15 12:00:00', 'INACTIVE');

